import { useState } from 'react';
import { useSearchParam, asString } from '../../url/useSearchParam';
import { PREVIEW_PARAM } from './usePreview';

// Sets or clears the signed-in user's preview date, and shows it (nothing when none). While it is set every figure on
// the screen is shown as if the sheet's today were that date; changes still use the real today. It is this screen's alone.
export function PreviewControl() {
  const [preview, setPreview] = useSearchParam(PREVIEW_PARAM, asString);
  const [date, setDate] = useState('');
  return (
    <form
      data-testid="preview-form"
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = date.trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) setPreview(trimmed);
      }}
    >
      Preview: <span data-testid="sheet-preview">{preview}</span>{' '}
      <input type="date" data-testid="preview-date" value={date} onChange={(e) => setDate(e.target.value)} />
      <button type="submit" data-testid="preview-set">Set preview</button>
      <button type="button" data-testid="preview-clear" onClick={() => setPreview(undefined)}>
        Clear preview
      </button>
    </form>
  );
}
import { asString, useSearchParam } from '../../url/useSearchParam';

/** The URL key holding the signed-in user's preview date ("" or absent: none). It is this screen's alone: other
 *  users, and the store, are unaffected. */
export const PREVIEW_PARAM = 'preview';

/** The preview date (YYYY-MM-DD), "" for none. While it is set every figure on screen is worked as if the sheet's
 *  today were that date, over the sheet's current records; every change still uses the sheet's real today. */
export function usePreview(): string {
  const [preview] = useSearchParam(PREVIEW_PARAM, asString);
  return preview;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';
import { usePreview } from '../preview/usePreview';

export type SheetToday = { sheet: string; today: string; archived: boolean };

export const sheetTodayKey = (sheet: string, asOf = '') => ['sheet', sheet, 'today', asOf] as const;

/** The sheet's today as figures are shown on it (YYYY-MM-DD; the as-of date while one is set, else the preview date while
 *  one is set). Every date decision and default date on screen reads this — never `new Date()`. Undefined while loading. */
export function useSheetToday(sheet: string): string | undefined {
  const preview = usePreview();
  const today = useRealSheetToday(sheet);
  const asOf = useAsOf();
  return asOf === '' && preview !== '' && today !== undefined ? preview : today;
}

/** The sheet's today whatever the preview date (the as-of date while one is set): what changes, and the rules
 *  the server judges them by, go on. Undefined while loading. */
export function useRealSheetToday(sheet: string): string | undefined {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet, asOf),
    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
    enabled: sheet !== '',
  });
  return data?.today;
}

/** Whether the sheet is archived (everything visible, every change refused). Undefined while loading. */
export function useSheetArchived(sheet: string): boolean | undefined {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet, asOf),
    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
    enabled: sheet !== '',
  });
  return data?.archived;
}
