import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { downloadCsv } from '../people/csv';
import { usePeople, type Person } from '../people/usePeople';
import { poolsKey, usePools, type Pool } from './usePools';

// The sheet's pools and the form that adds one (a blank name, or one already a pool, is refused). Each
// pool lists its members with their shares, its total share (a retired member's share counted as given) and whether
// it is balanced (the total is exactly 100.00), and adds a member from its row: a person already in the
// pool, or a share not more than 0.00 and at most 100.00 with two decimals, is refused. Each member of a balanced
// pool shows their cut of its pot (empty while the pool is unbalanced or has no pot). A retired or held member cuts 0.00, their share spread over
// the others in proportion to theirs; the rounding remainder goes to the member with the smallest non-zero cut (the latest
// added on a tie; with none, the last member with a cut); a pool whose every member is retired shows no cuts. A member may be another pool,
// chosen as pool:<name>: a pool is a member of at most one pool, never contains itself through any chain, and a chain
// of pools is at most three deep. A pool that is a member of none has the sheet's pot; a pool that is a member of
// another has its cut there as its pot. A membership may carry an optional from-date and to-date (a to-date before
// the from-date is refused); a member whose dates do not include the sheet's today is left out entirely: not in the
// total share, not in the balance, no cut. The export button downloads the pools as CSV: one line per member, pools
// and members in the order added, a pool member as pool:<name>, the cut as shown (empty when none). Every crew is also
// a pool of its name, listed after the pools in the order added: the lead and the members at equal shares (100.00 split
// as patrons' shares are, the remainder on the lead), given cuts like any pool. Its members come from the crew, so its
// row has no form to add one; a pool cannot take a crew's name, nor a crew a pool's. For every period whose to-date is
// on or before the sheet's today, each member also shows their cut as it stood at the end of that period (the pool,
// its members, the pot and the holds as they were then), empty when there was none. A closed or soft-closed period
// instead shows each member's cut as it stood when it was closed (whatever its to-date), until it is reopened.
export function PoolPanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const asOf = useAsOf();
  const pools = usePools(sheet);
  const people = usePeople(sheet);
  const [name, setName] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { name: string }) =>
      postJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools`, { ...body, user }),
    onSuccess: (saved) => {
      setName('');
      queryClient.setQueryData(poolsKey(sheet), saved);
    },
  });
  const exportPools = async () => {
    // Re-read so the cuts reflect any change made elsewhere on the screen since the pools were last fetched.
    const fresh = await queryClient.fetchQuery({
      queryKey: poolsKey(sheet, asOf),
      queryFn: () => getJson<Pool[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/pools`, asOf)),
      staleTime: 0,
    });
    downloadCsv('pools.csv', [
      ['pool', 'member', 'share', 'cut'],
      ...fresh.flatMap((p) => p.members.map((m) => [p.name, m.memberPool ? `pool:${m.memberPool}` : m.name, m.share, m.cut])),
    ]);
  };
  return (
    <>
      <button type="button" data-testid="export-pools" onClick={() => void exportPools()}>
        Export pools
      </button>
      <ul data-testid="pool-list">
        {pools.map((p) => (
          <PoolRow key={p.name} pool={p} pools={pools} people={people} sheet={sheet} user={user} />
        ))}
      </ul>
      <form
        data-testid="pool-form"

